async function copyBattleLog(detailed){const text=Game.exportLog(detailed,logViewer()),status=$('#copy-log-status');try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw Error('clipboard unavailable');status.textContent=(detailed?'詳細ログ':'通常ログ')+'を全文コピーしました。';}catch{const el=document.createElement('textarea');el.value=text;el.setAttribute('aria-label','コピーする対戦ログ');el.style.cssText='position:fixed;left:0;top:0;width:1px;height:1px';document.body.append(el);el.select();let copied=false;try{copied=document.execCommand('copy');}catch{}el.remove();if(copied)status.textContent='ログを全文コピーしました。';else{status.textContent='自動コピーできませんでした。全文を選択してコピーしてください。';openModal('対戦ログ全文',`<textarea id="manual-log-copy" readonly aria-label="対戦ログ全文">${esc(text)}</textarea>`,'log-copy');$('#manual-log-copy').select();}}}
$('#event-log').addEventListener('toggle',()=>{if($('#event-log').open){renderedLogKey='';renderBattleLog();$('#log-scroll').scrollTop=$('#log-scroll').scrollHeight;}});
